(() => {
  'use strict';
  const C=OSLabConcurrencyMovies,P=C.phase,E=C.esc,pick=C.select,node=C.node,badge=C.badge,page=document.body.dataset.page;
  const click=(attr,value)=>document.querySelector('['+attr+'="'+value+'"]')?.click();
  const receipt=(value,empty)=>value?'<span class="cm-received-task">'+E(value)+'</span>':E(empty);
  const itemNo=item=>item?.replace('任务 ','')||'';
  function decorate(frames, tracked){let receipts={},phase=-1;return frames.map((s,i)=>{const before=frames[i-1];if(i&&s.op==='take'&&s.queue.length<before.queue.length)receipts={...receipts,[s.actor]:before.queue[0]};if(tracked){if(s.actor===tracked&&['wait','unsafeSleep'].includes(s.op))phase=0;else if(phase===0&&s.states[tracked]?.includes('已通知'))phase=1;else if(phase===1&&s.actor===tracked&&s.op==='lock')phase=2;}return {...s,receipts:{...receipts},waitPhase:phase};});}
  function slots(s,prefix='queue'){return '<div class="cm-queue"><span>实际任务队列</span><div class="cm-queue-slots">'+Array.from({length:2},(_,i)=>'<div class="cm-slot '+(s.queue[i]?'cm-filled':'')+' '+(s.unpublished&&i>=s.queue.length-s.unpublished?'cm-unpublished':'')+'" data-node="'+prefix+'-slot-'+i+'">'+(s.queue[i]?'<b data-node="'+prefix+'-item-'+i+'">'+E(itemNo(s.queue[i]))+'</b>':'<i>空位</i>')+'</div>').join('')+'</div><small>'+s.queue.length+' 项 / 2 个位置'+(s.unpublished?' · 新任务尚未发布许可':'')+'</small></div>';}
  function cv(){const detail=C.wrap('cv-flow',['#cv-demo'],'wait、通知与逐操作回查');C.mount({id:'cv-flow',before:detail,controls:['[data-cv-scene]','[data-cv-variant]'],action:()=>{const scene=pick('data-cv-scene','empty');if(['gap','barging'].includes(scene))click('data-cv-variant',pick('data-cv-variant','safe')==='safe'?'unsafe':'safe');else click('data-cv-scene',scene==='empty'?'full':'empty');},actionLabel:()=>['gap','barging'].includes(pick('data-cv-scene','empty'))?pick('data-cv-variant','safe')==='safe'?'对照错误写法':'查看正确写法':'对照空队列与满队列',
    build(){const scenario=pick('data-cv-scene','empty'),variant=pick('data-cv-variant','safe'),tracked=scenario==='full'?'P':'C1',frames=decorate(OSLabConditionVariables.trace(scenario,variant),tracked),phases=[];
      frames.forEach((s,i)=>{const before=frames[i-1],returned=i&&s.op==='lock'&&before.states[s.actor]?.includes('已通知'),notified=i&&s.waitPhase===1&&before.waitPhase===0,gapNotice=scenario==='gap'&&variant==='unsafe'&&s.op==='signal',gapOpen=scenario==='gap'&&variant==='unsafe'&&i===3;if(i&&!['wait','unsafeSleep','put','take'].includes(s.op)&&!returned&&!notified&&!gapNotice&&!gapOpen&&i!==frames.length-1)return;
        let title,note,moves=[];if(!i){title=scenario==='full'?'两个位置都满了，生产者必须等空位':'队列为空，消费者不能凭空取任务';note=scenario==='full'?'两个位置都已有任务。生产者要等消费者取走任务、腾出空位，才能继续入队。':'任务块表示实际数据；消费者要等生产者放入任务，才能继续出队。';}
        else if(['wait','unsafeSleep'].includes(s.op)){title=s.lost?'任务已在队列里，C1 却错过通知并睡下':s.waitPhase===0&&before.waitPhase===2?'C1 发现任务已被取走，再次等待':s.actor+' 释放锁，进入等待区';note=s.lost?'P 发通知时 C1 还没登记等待；之后不再有新通知，已有任务也不会自动唤醒它。':s.actor==='P'?'生产者放下队列锁，消费者才能进来取走任务、腾出空位。':'等待时不占队列锁，生产者才能进来放入任务。';moves=[{from:'cv-chip',to:'cv-track-0',text:tracked,type:'cm-thread-token',remove:true}];}
        else if(s.op==='put'){title='P 放入任务 '+before.nextItem+'，队列现有 '+s.queue.length+' 项';note=s.waitPhase===0?'任务已经在队列中，但等待者还没有收到通知。':'这次入队占用一个实际空位，队列中的任务数量随之增加。';moves=[{from:'cv-produce',to:'queue-slot-'+before.queue.length,text:'任务 '+before.nextItem,type:'cm-task'}];}
        else if(s.op==='take'){title=s.error?'C1 按旧判断取任务，队列却已空':s.actor==='C2'?'C2 抢先取走任务，C1 还在等锁':s.actor+' 取走 '+before.queue[0];note=s.error?'被通知没有预留任务。重新获得锁后必须检查当前队列。':s.actor==='C2'?'C2 已经取走任务。C1 虽然收到通知，但没有获得或预留这项任务。':'取走实际任务后，队列空位随之增加。';if(!s.error)moves=[{from:'queue-item-0',to:'cv-receipt-'+s.actor,text:before.queue[0],type:'cm-task',remove:true}];}
        else if(notified){title=tracked+' 收到通知，还要等待重新获得锁';note='发通知的线程仍持有队列锁。通知没有转交锁，也没有为'+(tracked==='P'?'生产者预留空位。':'消费者预留任务。');moves=[{from:'cv-chip',to:'cv-track-1',text:tracked,type:'cm-thread-token',remove:true}];}
        else if(returned){title=tracked+' 重新获得锁，wait 才返回';note='现在可以重新检查共享队列；是否能操作，要以此时的任务或空位为准。';moves=[{from:'cv-chip',to:'cv-track-2',text:tracked,type:'cm-thread-token',remove:true}];}
        else if(gapNotice){title='P 发出通知时，没有线程在等待';note='通知不会保存为以后的许可；实际任务则继续留在队列里。';}
        else if(gapOpen){title='C1 已解锁，却还没有登记等待';note='这个间隙里，P 可以放入任务并发出通知，而 C1 尚不在等待队列。';}
        else {title=scenario==='full'?'空位出现后，生产者完成入队':'消费者取走任务后释放锁';note='实际队列、通知和获得锁是不同的变化，只有满足条件后才能修改队列。';}
        phases.push(P(s,title,note,{duration:i?1700:1100,before,moves,id:'frame-'+i,during: s.op==='put'?'任务正在入队':s.op==='take'?'任务正在交给 '+s.actor:title,duringNote:s.op==='put'?'P 正把任务放入队列；入队与发出通知是两个操作。':s.op==='take'?(s.actor==='C2'?'C2 正在取走任务；C1 收到的通知没有为它保留这项任务。':'消费者正在取出已确认存在的任务。出队完成后，才腾出一个实际空位。'):returned?'等待者正在重新取得队列锁；wait 返回后，才重新检查条件。':note}));
      });return{context:scenario==='barging'?'通知没有为 C1 预留任务':scenario==='gap'?'检查与登记等待必须衔接':scenario==='full'?'消费者腾出空位，生产者再继续':'生产者提供任务，消费者再继续',scenario,tracked,phases};},
    view(s,{story}){const mark=slot=>s.waitPhase===slot?'<b class="cm-tracked" data-node="cv-chip">'+story.tracked+'</b>':'';return '<div class="cm-queue-scene" data-error="'+Boolean(s.error||s.lost)+'"><div class="cm-port cm-producer"><strong>生产者 P</strong><span data-node="cv-produce" class="cm-task-source">'+(s.produced?'已放入':'待放任务 '+s.nextItem)+'</span><small>'+E(s.states.P)+'</small>'+(story.tracked==='P'&&s.waitPhase<0?'<b class="cm-tracked" data-node="cv-chip">P</b>':'')+'</div>'+slots(s)+'<div class="cm-port cm-consumer"><strong>消费者 C1</strong><span data-node="cv-receipt-C1" class="cm-receipt">'+receipt(s.receipts.C1,'尚未取走')+'</span><small>'+E(s.error?'空队列取走失败':s.states.C1)+'</small>'+(story.tracked==='C1'&&s.waitPhase<0?'<b class="cm-tracked" data-node="cv-chip">C1</b>':'')+'</div><div class="cm-queue-lock">队列锁：'+(s.lock?s.lock+' 持有':'已释放，可以争取')+'</div><div class="cm-other-consumer '+(story.scenario==='barging'?'':'cm-no-other')+'"><span>C2 抢先取得的任务</span><b data-node="cv-receipt-C2">'+receipt(s.receipts.C2,'尚未取走')+'</b></div><div class="cm-wait-track">'+['等待通知','等待重新获锁','已重新获锁'].map((label,i)=>'<div data-node="cv-track-'+i+'"><span>'+label+'</span>'+mark(i)+'</div>').join('')+'</div></div>';}
  });}
  function permits(){const detail=C.wrap('permit-flow',['#permit-demo'],'许可数量与调用过程回查');C.mount({id:'permit-flow',before:detail,controls:['[data-permit-kind]','[data-permit-order]'],action:()=>{const kind=pick('data-permit-kind','resources');if(kind==='order')click('data-permit-order',pick('data-permit-order','postFirst')==='postFirst'?'waitFirst':'postFirst');else click('data-permit-kind',kind==='resources'?'mutex':'resources');},actionLabel:()=>pick('data-permit-kind','resources')==='order'?'交换 post 与 wait':pick('data-permit-kind','resources')==='resources'?'对照单许可':'对照双许可',
    build(){const kind=pick('data-permit-kind','resources'),frames=OSLabSemaphores.permitTrace(kind,pick('data-permit-order','postFirst')),phases=frames.map((s,i)=>{const before=frames[i-1],success=i&&s.waits>before.waits;let moves=[];if(success)moves=[{from:'available-0',to:'grant-'+s.actor,text:'许可',type:'cm-permit',remove:true}];if(i&&s.op==='post')moves=[{from:'grant-'+s.actor,to:'permit-bank',text:'许可',type:'cm-permit',remove:kind!=='order'}];return P(s,!i?(kind==='order'?'A 等 B 发布许可后，才能继续执行':'可用许可 '+s.available+' 个，拿到许可才能进入'):success?s.actor+' 取得许可，wait 成功返回':s.op==='wait'?s.actor+' 无许可可取，停在入口外':s.op==='post'?s.actor+' 发布许可，等待者还需完成 wait':s.actor+' 正在使用已取得的名额',!i?(kind==='order'?'这里的许可代表已经发生的通知；post 可以先于 wait，许可仍会保留。':'圆形表示使用名额，不是实际的任务或数据。'):s.op==='post'?(kind==='order'?'post 增加可用许可；被唤醒的 A 仍需完成 wait，才能消耗它并继续。':'许可先回到可用池；被唤醒不等于已经拿到它。'):success?'一个可用许可被消耗，取得者才可以继续。':'没有可用许可，其他线程不能开始使用资源。',{duration:i?1500:1000,before,moves,id:'frame-'+i,during:s.op==='post'?'一个许可正在变为可用':s.actor+' 正在取得许可',duringNote:s.op==='post'?'post 增加可用许可，等待者随后才有机会取得。':s.actor+' 正在取得一个可用许可；成功取得后，wait 才能返回。'});});return{context:kind==='order'?'post 先发生，许可也能留给后来的 wait':'许可控制可同时使用的名额',kind,phases};},
    view(s,{story}){return '<div class="cm-permits"><div class="cm-permit-pool" data-node="permit-bank"><span>可用许可</span><div>'+ (s.available?Array.from({length:s.available},(_,i)=>'<b class="cm-coin" data-node="available-'+i+'">1</b>').join(''):'<strong class="cm-empty-bank">0</strong>')+'</div><small>'+s.available+' 个名额可取得</small></div><div class="cm-permit-people">'+Object.entries(s.states).map(([who,state])=>'<div class="cm-permit-person '+(s.grants.includes(who)?'cm-admitted':'cm-outside')+'">'+badge(who)+'<div class="cm-grant" data-node="grant-'+who+'">'+(s.grants.includes(who)?'<b class="cm-coin">1</b>':'<span>'+(story.kind==='order'&&who==='B'?'post()':'无许可')+'</span>')+'</div><small>'+E(state)+'</small></div>').join('')+'</div><div class="cm-permit-count">已成功取得 '+s.waits+' 次；发布 '+s.posts+' 次</div></div>';}
  });}
  function buffer(){const detail=C.wrap('buffer-flow',['#buffer-demo'],'许可预留与实际出入队回查');C.mount({id:'buffer-flow',before:detail,controls:['[data-buffer-scene]','[data-buffer-variant]'],action:()=>{if(pick('data-buffer-scene','empty')==='empty')click('data-buffer-scene','full');else click('data-buffer-variant',pick('data-buffer-variant','safe')==='safe'?'unsafe':'safe');},actionLabel:()=>pick('data-buffer-scene','empty')==='empty'?'对照满队列':pick('data-buffer-variant','safe')==='safe'?'对照持锁等待':'先取许可，再加锁',
    build(){const scenario=pick('data-buffer-scene','empty'),variant=pick('data-buffer-variant','safe'),frames=decorate(OSLabSemaphores.queueTrace(scenario,variant)),phases=[];frames.forEach((s,i)=>{const before=frames[i-1];if(i&&['lock','unlock'].includes(s.op)&&!s.error&&!(variant==='unsafe'&&i===1)&&i!==frames.length-1)return;let title,note,moves=[];if(!i){title='实际任务与可用许可是两套记录';note='方块是任务，圆片是许可。先获得许可，再加锁改变实际队列。';}else if(s.op==='wait'){const success=s[s.channel]<before[s.channel];title=success?s.actor+' 取得'+(s.channel==='empty'?'空位':'任务')+'许可，数据还没移动':s.actor+' 等待'+(s.channel==='empty'?'空位':'任务')+'许可';note=success?'取得许可只预留操作机会；队列本身暂时保持原样。':s.lock===s.actor?'等待信号量不会释放已经持有的队列锁。':'等待时没有占队列锁，另一方可以改变队列并发布许可。';if(success)moves=[{from:s.channel+'-coin-0',to:'buffer-grant-'+s.actor,text:s.channel==='empty'?'空位':'任务',type:'cm-permit',remove:true}];}
      else if(s.op==='put'){title='任务已放入，但任务许可还没发布';note='实际队列先改变，消费者可取得的 full 许可要等 post 后才增加。';moves=[{from:'buffer-produce',to:'queue-slot-'+before.queue.length,text:'任务 '+before.nextItem,type:'cm-task'}];}
      else if(s.op==='take'){title='任务已取走，但空位许可还没归还';note='实际空位已出现，生产者仍要等 post(empty) 发布这份许可。';moves=[{from:'queue-item-0',to:'buffer-receipt',text:before.queue[0],type:'cm-task',remove:true}];}
      else if(s.op==='post'){title=s.actor+' 发布'+(s.channel==='empty'?'空位':'任务')+'许可';note='许可进入可用池；实际任务在这一步不会再次移动。';moves=[{from:'buffer-post-'+s.actor,to:s.channel+'-bank',text:s.channel==='empty'?'空位':'任务',type:'cm-permit'}];}
      else {title=s.error?'P 占锁等空位，C1 却拿不到锁来腾空':'P 先持有了队列锁';note=s.error?'P 不释放锁，C1 就不能取走任务；C1 不能取走，P 就等不到空位。':'接着等待空位时，这把锁不会自动释放。';}
      phases.push(P(s,title,note,{duration:!i?1100:1500,before,moves,id:'frame-'+i,during:s.op==='put'?'实际任务正在入队':s.op==='take'?'实际任务正在取出':'操作许可正在转移',duringNote:s.op==='put'?'先把实际任务放进队列，之后再发布任务许可。':s.op==='take'?'实际任务正在交给消费者；出队完成后再发布空位许可。':note}));});return{context:scenario==='full'?'队列初始已满':'队列初始为空',scenario,variant,phases};},
    view(s){const bank=channel=>'<div class="cm-small-bank" data-node="'+channel+'-bank"><span>'+ (channel==='empty'?'空位许可':'任务许可')+'</span><div>'+ (s[channel]?Array.from({length:s[channel]},(_,i)=>'<b class="cm-coin" data-node="'+channel+'-coin-'+i+'">1</b>').join(''):'<b>0</b>')+'</div></div>';return '<div class="cm-buffer" data-error="'+s.error+'"><div class="cm-buffer-banks">'+bank('empty')+bank('full')+'</div><div class="cm-buffer-main"><div class="cm-port"><strong>P · 生产者</strong><span data-node="buffer-grant-P" class="cm-reservation">'+(s.reservedEmpty?'<b class="cm-coin">空位</b>':'待取许可')+'</span><span data-node="buffer-produce" class="cm-task-source">'+(s.produced?'已放入':'任务 '+s.nextItem)+'</span><span data-node="buffer-post-P" class="cm-post-point">post(full)</span></div>'+slots(s)+'<div class="cm-port"><strong>C1 · 消费者</strong><span data-node="buffer-grant-C1" class="cm-reservation">'+(s.reservedFull?'<b class="cm-coin">任务</b>':'待取许可')+'</span><span data-node="buffer-receipt" class="cm-receipt">'+receipt(s.receipts.C1,'尚未取出')+'</span><span data-node="buffer-post-C1" class="cm-post-point">post(empty)</span></div></div><div class="cm-queue-lock '+(s.error?'cm-deadlocked':'')+'">队列锁：'+(s.lock?s.lock+' 持有':'空闲')+(s.error?' · 双方相互等待':'')+'</div><div class="cm-buffer-states"><span>P：'+E(s.states.P)+'</span><span>C1：'+E(s.states.C1)+'</span></div></div>';}
  });}
  if(page==='conditionVariables')cv();if(page==='semaphores'){permits();buffer();}
})();
